{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    raw_edges = case['distances']

    # build all mutual reachability edges with canonical ordering
    edges = []
    for u, v, d in raw_edges:
        if u > v:
            u, v = v, u
        mutual = max(core[u], core[v], d)
        edges.append((u, v, mutual))

    # sort by mutual reachability, then by node ids
    edges.sort(key=lambda x: (x[2], x[0], x[1]))

    # union-find structure
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    # Check connectivity (should never happen with valid input, but safe guard)
    if len(mst_edges) != n - 1:
        raise ValueError('Disconnected input: cannot form a spanning tree')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
